import { cn } from '@/lib/utils'

/**
 * The selectable-tile recipe: a bordered square that fills with the accent when
 * chosen.
 *
 * `ToggleGroup` (pick one) and `CheckboxGroup` (pick any) both draw from this,
 * so the two stay visually identical by construction rather than by vigilance.
 *
 * Exported so an app can build a tile the two group components do not cover --
 * Chip Away's icon picker renders a glyph rather than a label, and its weekday
 * strip is seven single characters. Reach for a group component first; this is
 * for the case where the layout genuinely differs but the tile should not.
 */
export interface OptionTileOptions {
  /** Renders the accent fill and raises the tile. */
  selected: boolean
  /** Dims and blocks pointer events, without removing it from the tab order. */
  disabled?: boolean
  /** Stacks an icon above the label instead of centering a lone label. */
  stacked?: boolean
}

export function optionTileClass({ selected, disabled, stacked }: OptionTileOptions): string {
  return cn(
    'wj-focus-ring relative rounded-xl border-2 px-3 py-3 text-sm font-medium transition-all',
    stacked ? 'flex flex-col items-center gap-1.5' : 'flex items-center justify-center',
    selected
      ? 'bg-[var(--color-accent-500)] border-[var(--color-accent-500)] text-[var(--color-accent-foreground)] shadow-md'
      : [
          'bg-[var(--color-surface-light)] border-[var(--color-border-light)]',
          'text-[var(--color-text-secondary-light)]',
          'hover:border-[var(--color-accent-400)]',
          'dark:bg-[var(--color-surface-dark)] dark:border-[var(--color-border-dark)]',
          'dark:text-[var(--color-text-secondary-dark)]',
          'dark:hover:border-[var(--color-neutral-500)]',
        ],
    // Kept tabbable on purpose: a disabled option a keyboard user cannot reach is
    // an option they cannot discover the existence of.
    disabled && 'opacity-50 pointer-events-none',
  )
}
